package com.smartdoc.ai.provider;
import com.smartdoc.ai.SecretPersistenceException; import javax.crypto.*; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import java.nio.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.Base64;
public final class AesGcmSecretCipher implements SecretCipher { private static final int NONCE_BYTES=12,TAG_BITS=128; private final SecretKey key; private final SecureRandom random=new SecureRandom(); private AesGcmSecretCipher(byte[] raw){key=new SecretKeySpec(raw,"AES");} public static AesGcmSecretCipher fromBase64(String encoded){try{byte[] raw=Base64.getDecoder().decode(encoded==null?"":encoded.trim());if(raw.length!=32)throw new IllegalArgumentException("AI master key must be exactly 32 bytes");return new AesGcmSecretCipher(raw);}catch(IllegalArgumentException e){throw e;}}
 public String encrypt(String plain,String aad){try{byte[] nonce=new byte[NONCE_BYTES];random.nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(TAG_BITS,nonce));c.updateAAD(aad.getBytes(StandardCharsets.UTF_8));byte[] body=c.doFinal(plain.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(ByteBuffer.allocate(nonce.length+body.length).put(nonce).put(body).array());}catch(GeneralSecurityException e){throw new SecretPersistenceException("AI key encryption failed",e);}}
 public String decrypt(String value,String aad){try{byte[] all=Base64.getDecoder().decode(value);if(all.length<=NONCE_BYTES)throw new GeneralSecurityException();ByteBuffer b=ByteBuffer.wrap(all);byte[] nonce=new byte[NONCE_BYTES];b.get(nonce);byte[] body=new byte[b.remaining()];b.get(body);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(TAG_BITS,nonce));c.updateAAD(aad.getBytes(StandardCharsets.UTF_8));return new String(c.doFinal(body),StandardCharsets.UTF_8);}catch(IllegalArgumentException|GeneralSecurityException e){throw new SecretPersistenceException("AI key decryption failed",e);}}
}
